commit 7df7908c12fb2ca0ee7cf95aba090281172a051f
Author: lab <lab@example.invalid>
Date:   Sat Sep 19 18:04:45 2026 +0200

    fix: round a negative half cent away from zero

    Cut: the Math.round tie that sent -0.005 to -0.00

 src/money/round.js      | 6 ++++--
 src/money/round.test.js | 4 ++++
 2 files changed, 8 insertions(+), 2 deletions(-)
=== DIFF ===
diff --git a/src/money/round.js b/src/money/round.js
index 5e449b5..1bec0d7 100644
--- a/src/money/round.js
+++ b/src/money/round.js
@@ -1,6 +1,8 @@
-// Round a money amount to whole cents.
+// Round a money amount to whole cents, half away from zero.
+// Math.round ties toward +Infinity, so -0.005 came out as -0.00.
 function roundCents(amount) {
-  return Math.round(amount * 100) / 100;
+  const sign = amount < 0 ? -1 : 1;
+  return (sign * Math.round(Math.abs(amount) * 100)) / 100;
 }

 module.exports = { roundCents };
diff --git a/src/money/round.test.js b/src/money/round.test.js
index 66ab8fe..bf0c71d 100644
--- a/src/money/round.test.js
+++ b/src/money/round.test.js
@@ -8,3 +8,7 @@ test("keeps an amount that is already whole cents", () => {
 test("rounds a third of a cent down", () => {
   assert.strictEqual(roundCents(1.231), 1.23);
 });
+
+test("rounds a negative half cent away from zero", () => {
+  assert.strictEqual(roundCents(-0.005), -0.01);
+});

